import crypto from 'node:crypto';
import {safeUrl} from './net.js';
import {opaque,persist} from './sessions.js';
import {parsePlaylist} from './m3u.js';
import {parseGuide,currentPrograms} from './xmltv.js';

// Copy these URLs from FastChannels > Feeds. Bridge feed URLs are generated by
// FastChannels and MUST NOT be inferred from the ordinary feed URL.
const feeds=[
  {kind:'clear',m3u:process.env.FASTCHANNELS_M3U_URL,epg:process.env.FASTCHANNELS_EPG_URL},
  {kind:'bridge',m3u:process.env.FASTCHANNELS_BRIDGE_M3U_URL,epg:process.env.FASTCHANNELS_BRIDGE_EPG_URL}
].filter(f=>f.m3u?.trim()).map(f=>({kind:f.kind,m3u:f.m3u.trim(),epg:f.epg?.trim()||''}));
const CACHE_MS=60_000,GUIDE_CACHE_MS=5*60_000,MAX_M3U_BYTES=3_000_000,MAX_XMLTV_BYTES=18_000_000;
const cache=new Map(),guideCache=new Map();
const activeLoads=new Map();

async function readBounded(url,limit){
  let current=url;
  for(let redirects=0;redirects<4;redirects++){
    await safeUrl(current);
    const r=await fetch(current,{redirect:'manual',signal:AbortSignal.timeout(18000)});
    if(r.status>=300&&r.status<400){
      const location=r.headers.get('location');
      if(!location)throw new Error('Feed redirected without a Location header');
      current=new URL(location,current).href;
      continue;
    }
    if(!r.ok)throw new Error('Feed HTTP '+r.status);
    if(Number(r.headers.get('content-length')||0)>limit)throw new Error('Feed exceeds '+limit+' byte limit');
    const reader=r.body?.getReader();
    if(!reader)throw new Error('Empty feed');
    let bytes=0;
    const chunks=[];
    try{
      while(true){
        const {value,done}=await reader.read();
        if(done)break;
        bytes+=value.byteLength;
        if(bytes>limit){await reader.cancel();throw new Error('Feed exceeded '+limit+' byte limit');}
        chunks.push(value);
      }
    }finally{reader.releaseLock();}
    return {body:Buffer.concat(chunks).toString('utf8'),url:current};
  }
  throw new Error('Feed exceeded redirect limit');
}

async function loadFeed(feed,force){
  const now=Date.now(),saved=cache.get(feed.kind);
  if(!force&&saved&&now-saved.at<CACHE_MS)return saved.value;
  const key=feed.kind+':m3u';
  if(activeLoads.has(key))return activeLoads.get(key);
  const promise=(async()=>{
    const response=await readBounded(feed.m3u,MAX_M3U_BYTES);
    const parsed=parsePlaylist(response.body,response.url);
    const channels=[];
    for(const channel of parsed){
      try{
        await safeUrl(channel.url);
        // Channel ids have a feed-specific prefix in their hash, so a clear
        // feed and a capture bridge feed can coexist without collisions.
        const id=crypto.createHash('sha256').update(feed.kind).update(':').update(channel.id).digest('hex').slice(0,24);
        channels.push({...channel,id,kind:feed.kind,bridge:feed.kind==='bridge'});
      }catch{}
    }
    cache.set(feed.kind,{at:Date.now(),value:channels});
    return channels;
  })().finally(()=>activeLoads.delete(key));
  activeLoads.set(key,promise);
  return promise;
}

async function loadGuide(feed,force){
  if(!feed.epg)return new Map();
  const now=Date.now(),saved=guideCache.get(feed.kind);
  if(!force&&saved&&now-saved.at<GUIDE_CACHE_MS)return saved.value;
  const key=feed.kind+':epg';
  if(activeLoads.has(key))return activeLoads.get(key);
  const promise=(async()=>{
    const {body}=await readBounded(feed.epg,MAX_XMLTV_BYTES);
    const guide=parseGuide(body,{from:Date.now()-3600000,to:Date.now()+8*3600000});
    guideCache.set(feed.kind,{at:Date.now(),value:guide});
    return guide;
  })().finally(()=>activeLoads.delete(key));
  activeLoads.set(key,promise);
  return promise;
}

export async function channels(force=false){
  if(!feeds.length)return {configured:false,channels:[],errors:[]};
  const all=[],errors=[];
  const collected=await Promise.all(feeds.map(async feed=>{
    try{return {feed,channels:await loadFeed(feed,force)};}
    catch(error){return {feed,error};}
  }));
  for(const result of collected){
    if(result.error){
      errors.push({feed:result.feed.kind,message:String(result.error.message)});
      continue;
    }
    all.push(...result.channels);
  }
  return {configured:true,channels:all,errors};
}

export async function lineup(force=false,at=Date.now()){
  const base=await channels(force);
  if(!base.configured)return base;
  const guideMap=new Map(),errors=[...base.errors];
  await Promise.all(feeds.map(async feed=>{
    if(!feed.epg)return;
    try{guideMap.set(feed.kind,await loadGuide(feed,force));}
    catch(error){errors.push({feed:feed.kind+' EPG',message:String(error.message)});}
  }));
  return {...base,errors,channels:base.channels.map(c=>{
    const guide=guideMap.get(c.kind);
    const events=guide?.get(c.tvgId)||guide?.get(c.name)||[];
    const {now,next}=currentPrograms(events,at);
    // Do not return stream URLs or session tokens in channel listings.
    return {id:c.id,name:c.name,group:c.group,channelNumber:c.channelNumber,
      tvgId:c.tvgId,kind:c.kind,bridge:c.bridge,now,next};
  })};
}

export async function select(session,id){
  if(typeof id!=='string'||!/^[a-f0-9]{24}$/.test(id))throw new Error('Invalid channel ID');
  const all=await channels();
  const channel=all.channels.find(c=>c.id===id);
  if(!channel)throw new Error('Channel unavailable; reload the guide');
  await safeUrl(channel.url);
  const streamId=opaque(session.streams,
    {url:channel.url,type:'live',videoId:channel.id,live:true,bridge:channel.bridge},3600000);
  persist(session);
  return {streamId,title:channel.name,group:channel.group,bridge:channel.bridge};
}

export function configuredFeeds(){
  return feeds.map(x=>({kind:x.kind,epgConfigured:Boolean(x.epg)}));
}
